function insRow7()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Texto original de la Ley 769 de 2002, </span>Art&iacute;culo INEXEQUIBLE<span class='b_aj'>:</span></p><p>ART&Iacute;CULO 128. MECANISMO DE SUBASTA DE VEH&Iacute;CULOS ABANDONADOS. Los organismos de tr&aacute;nsito podr&aacute;n disponer de los veh&iacute;culos inmovilizados por infracciones en los parqueaderos autorizados a trav&eacute;s del procedimiento de p&uacute;blica subasta, con arreglo al Estatuto General de Contrataci&oacute;n de la Administraci&oacute;n P&uacute;blica en un t&eacute;rmino no inferior a un (1) a&ntilde;o, excepto aquellos casos pendientes de un proceso judicial, en los cuales los organismos de tr&aacute;nsito particulares podr&aacute;n solicitar que se incluyan, como costas procesales, el valor de servicios de parqueadero. El Ministerio de Transporte expedir&aacute; el procedimiento para llevar a cabo lo establecido en el presente art&iacute;culo.</p><p>PAR&Aacute;GRAFO. No obstante, en cualquier tiempo el propietario podr&aacute; hacer entrega voluntaria del veh&iacute;culo al organismo de tr&aacute;nsito, quien podr&aacute; disponer del mismo y cancelar con cargo a &eacute;l, el valor de la multa y dem&aacute;s costos asociados con la inmovilizaci&oacute;n.</p> </td></tr></tbody>";
var z=document.getElementById('Table7').rows[0];
if (z==null) {
              var x=document.getElementById('Table7').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table7').deleteRow(0)
             }
}
