function insRow90()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Texto original de la Ley 769 de 2002:</span></p><p>ART&Iacute;CULO 146. Las autoridades de tr&aacute;nsito podr&aacute;n emitir conceptos t&eacute;cnicos sobre la responsabilidad en el choque y la cuant&iacute;a de los da&ntilde;os. A trav&eacute;s del procedimiento y audiencia p&uacute;blica dentro de los diez (10) d&iacute;as h&aacute;biles siguientes a la presentaci&oacute;n del informe. En caso de requerirse la pr&aacute;ctica de pruebas &eacute;stas se realizar&aacute;n en un t&eacute;rmino no superior a los diez (10) d&iacute;as h&aacute;biles, notificado en estrados previo agotamiento de la v&iacute;a gubernativa.</p><p>En los procesos que versen sobre indemnizaci&oacute;n de perjuicios causados por accidentes de tr&aacute;nsito, una vez dictada la sentencia de primera instancia, sin importar que &eacute;sta sea apelada o no, el juez decretar&aacute; el embargo y secuestro del veh&iacute;culo con el cual se caus&oacute; el da&ntilde;o, siempre y cuando el solicitante preste cauci&oacute;n que garantice el pago de los perjuicios que con la medida puedan causarse. Tal medida se regir&aacute; por las normas del libro IV del C&oacute;digo de Procedimiento Civil, y se levantar&aacute; si el condenado presta cauci&oacute;n suficiente, o cuando en recurso de apelaci&oacute;n se revoque la sentencia condenatoria o si el demandante no promueve la ejecuci&oacute;n en el t&eacute;rmino se&ntilde;alado en el art&iacute;culo <A href='codigo_procedimiento_civil_pr011.html#335' >335</A> del C&oacute;digo de Procedimiento Civil, o si se extingue de cualquier otra manera la obligaci&oacute;n.</p><p>Las medidas cautelares y las condenas econ&oacute;micas en esta clase de procesos, no podr&aacute;n exceder el monto indexado de los perjuicios realmente demostrados en &eacute;l mismo.</p> </td></tr></tbody>";
var z=document.getElementById('Table90').rows[0];
if (z==null) {
              var x=document.getElementById('Table90').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table90').deleteRow(0)
             }
}
